class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        k = len(set(nums))
        count = {}
        distinct = 0
        right = 0
        result = 0
        for left in range(n):
            while right < n and distinct < k:
                x = nums[right]
                if count.get(x, 0) == 0:
                    distinct += 1
                count[x] = count.get(x, 0) + 1
                right += 1
            if distinct == k:
                result += n - right + 1
            else:
                break
            y = nums[left]
            count[y] -= 1
            if count[y] == 0:
                distinct -= 1
        return result
