class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        K = len(set(nums))
        total = 0
        for i in range(n):
            freq = {}
            distinct = 0
            found = -1
            for j in range(i, n):
                v = nums[j]
                if freq.get(v, 0) == 0:
                    distinct += 1
                freq[v] = freq.get(v, 0) + 1
                if distinct == K:
                    found = j
                    break
            if found != -1:
                total += n - found
        return total
